def append_card(text,id,note,status=None):
    pattern=r'(^### '+re.escape(id)+r'\n)(.*?)(?=^### |\Z)'
    m=re.search(pattern,text,re.M|re.S);assert m,id
    body=m[2]
    if status:body=re.sub(r'Статус: \*\*[^*]+\*\*','Статус: **'+status+'**',body,count=1)
    body=body.rstrip()+'\n\n- Дополнение LOG-20261017-04: '+note+' [Отчёт]('+report+').\n\n'
    return text[:m.start()]+m[1]+body+text[m.end():]
